#include &lt;stdio.h&gt;
#include "peripherals.h"

// Lab-Specific Hardware Configuration Macros
#define SPEAKER_PIN       3   // Assigned output on Port B (corresponds to D13 board mapping)
#define NOTE_GAP_MS       15  // Quiet window interval between consecutive pitch changes
#define PLAYBACK_TRACK    0   // Mux selector: 1 = Für Elise, 0 = Ode to Joy

// Volatile global tracking variable
volatile uint32_t globalMillisecondsCounter = 0;

// ============================================================================
// 1. Music Composition Arrays (Pitches in Hz, Durations in ms)
// ============================================================================
