Reveal C Code: peripherals.h

/* RESOURCES:
- tutorial-clock-configuration starter code: STM32L432KC_RCC.h / RCC.c (RCC for TIM2)
                                             STM32L432KC_GPIO.h / GPIO.c (for TIM2, SysTick, GPIO)
- STM32L432KC reference manual, programming manual
*/

// peripherals.h
// Attempted to design code to be portable / can be dropped into another lab unmodified

#ifndef PERIPHERALS_H
#define PERIPHERALS_H

#include &lt;stdint.h&gt;

#define __IO volatile


// ============================================================================
// Definitions
// ============================================================================

//=========Memory Maps & Base Offsets=======
#define RCC_BASE      (0x40021000) // Base address for Reset and Clock Control (RCC)
#define GPIOB_BASE    (0x48000400) // Base address for GPIO Port B
#define TIM2_BASE     (0x40000000) // Base address for Timer 2 (Core timer peripheral) (from RM Section 2.2.2 Table 2)

// Private Peripheral Bus (PPB) Core Spaces (Reference: Cortex-M4 Device User Guide)
#define NVIC_BASE     (0xE000E100) // Nested Vectored Interrupt Controller Base
#define SYSTICK_BASE  (0xE000E010) // Core SysTick time register block (from PM Section 4.5 Table 54)

//===========Descriptive Peripheral Hardware Typedef Layouts============= 

// For RCC (from STM_RCC.h tutorial code)
typedef struct {
    __IO uint32_t CR;          // Offset 0x00 Clock control register
    __IO uint32_t ICSCR;       // 0x04 Internal clock sources calibration register
    __IO uint32_t CFGR;        // 0x08 Clock configuration register
    __IO uint32_t PLLCFGR;     // 0x0C System PLL configuration register
    __IO uint32_t PLLSAI1CFGR; // 0x10 PLL SAI1 configuration register
    uint32_t      RESERVED;    // 0x14 Reserved
    __IO uint32_t CIER;        // 0x18 Clock interrupt enable register
    __IO uint32_t CIFR;        // 0x1C Clock interrupt flag register
    __IO uint32_t CICR;        // 0x20 Clock interrupt clear register
    uint32_t      RESERVED0;   // 0x24 Reserved
    __IO uint32_t AHB1RSTR;    // 0x28 AHB1 peripheral reset register
    __IO uint32_t AHB2RSTR;    // 0x2C AHB2 peripheral reset register
    __IO uint32_t AHB3RSTR;    // 0x30 AHB3 peripheral reset register
    uint32_t      RESERVED1;   // 0x34 Reserved
    __IO uint32_t APB1RSTR1;   // 0x38 APB1 peripheral reset register 1
    __IO uint32_t APB1RSTR2;   // 0x3C APB1 peripheral reset register 2
    __IO uint32_t APB2RSTR;    // 0x40 APB2 peripheral reset register
    uint32_t      RESERVED2;   // 0x44 Reserved
    __IO uint32_t AHB1ENR;     // 0x48 AHB1 peripheral clocks enable register
    __IO uint32_t AHB2ENR;     // 0x4C AHB2 peripheral clocks enable register
    __IO uint32_t AHB3ENR;     // 0x50 AHB3 peripheral clocks enable register
    uint32_t      RESERVED3;   // 0x54 Reserved
    __IO uint32_t APB1ENR1;    // 0x58 APB1 peripheral clocks enable register 1
    __IO uint32_t APB1ENR2;    // 0x5C APB1 peripheral clocks enable register 2
    __IO uint32_t APB2ENR;     // 0x60 APB2 peripheral clocks enable register
    uint32_t      RESERVED4;   // Reserved,                                                                Address offset: 0x64 */
    __IO uint32_t AHB1SMENR;   // RCC AHB1 peripheral clocks enable in sleep and stop modes register,      Address offset: 0x68 */
    __IO uint32_t AHB2SMENR;   // RCC AHB2 peripheral clocks enable in sleep and stop modes register,      Address offset: 0x6C */
    __IO uint32_t AHB3SMENR;   // RCC AHB3 peripheral clocks enable in sleep and stop modes register,      Address offset: 0x70 */
    uint32_t      RESERVED5;   // Reserved,                                                                Address offset: 0x74 */
    __IO uint32_t APB1SMENR1;  // RCC APB1 peripheral clocks enable in sleep mode and stop modes register 1, Address offset: 0x78 */
    __IO uint32_t APB1SMENR2;  // RCC APB1 peripheral clocks enable in sleep mode and stop modes register 2, Address offset: 0x7C */
    __IO uint32_t APB2SMENR;   // RCC APB2 peripheral clocks enable in sleep mode and stop modes register, Address offset: 0x80 */
    uint32_t      RESERVED6;   // Reserved,                                                                Address offset: 0x84 */
    __IO uint32_t CCIPR;       // RCC peripherals independent clock configuration register,                Address offset: 0x88 */
    uint32_t      RESERVED7;   // Reserved,                                                                Address offset: 0x8C */
    __IO uint32_t BDCR;        // RCC backup domain control register,                                      Address offset: 0x90 */
    __IO uint32_t CSR;         // RCC clock control & status register,                                     Address offset: 0x94 */
    __IO uint32_t CRRCR;       // RCC clock recovery RC register,  
} RCC_TypeDef;

// For GPIO register structs (from STM_GPIO.h tutorial code)
typedef struct {
    volatile uint32_t MODER;   // GPIO Offset 0x00 GPIO port mode register
    volatile uint32_t OTYPER;  // GPIO Offset 0x04
    volatile uint32_t OSPEEDR; // GPIO Offset 0x08
    volatile uint32_t PURPDR;  // GPIO Offset 0x0C
    volatile uint32_t IDR;     // GPIO Offset 0x10
    volatile uint32_t ODR;     // GPIO Offset 0x14
    volatile uint32_t BSRR;    // GPIO Offset 0x18
    volatile uint32_t LCKR;    // GPIO Offset 0x1C
    volatile uint32_t AFRL;    // GPIO Offset 0x20
    volatile uint32_t AFRH;    // GPIO Offset 0x24
} GPIO_TypeDef;

// For TIM2
typedef struct {
    volatile uint32_t CR1;     // Offset 0x00 Control register 1
    volatile uint32_t CR2;     // 0x04 Control register 2
    volatile uint32_t SMCR;    // 0x08 Slave mode control register
    volatile uint32_t DIER;    // 0x0C DMA/Interrupt enable register
    volatile uint32_t SR;      // 0x10 Status register
    volatile uint32_t EGR;     // 0x14 Event generation register
    volatile uint32_t CCMR1;   // 0x18 Capture/compare mode register 1
    volatile uint32_t CCMR2;   // 0x1C Capture/compare mode register 2
    volatile uint32_t CCER;    // 0x20 Capture/compare enable register
    volatile uint32_t CNT;     // 0x24 Counter register
    volatile uint32_t PSC;     // 0x28 Prescaler register
    volatile uint32_t ARR;     // 0x2C Auto-reload register
} TIM_TypeDef;

// For SysTick register structs 
typedef struct {
    volatile uint32_t CTRL;    // Offset 0x00 SysTick Control and Status Register
    volatile uint32_t LOAD;    // 0x04 SysTick Reload Value Register
    volatile uint32_t VAL;     // 0x08 SysTick Current Value Register
    volatile uint32_t CALIB;  // 0x0C Calibration Value Register

} SysTick_TypeDef;

typedef struct {
    volatile uint32_t ISER[8]; // 0x00 Interrupt Set-Enable Registers Array
} NVIC_TypeDef;

// Instance Mapping Pointers 
#define RCC          ((RCC_TypeDef *) RCC_BASE)
#define GPIOB        ((GPIO_TypeDef *) GPIOB_BASE)
#define TIM2         ((TIM_TypeDef *) TIM2_BASE) // Pointers to TIM2-sized chunks of memory for each peripheral
#define SysTick_Core ((SysTick_TypeDef *) SYSTICK_BASE)
#define NVIC_Core    ((NVIC_TypeDef *) NVIC_BASE)

//==========Functional Parameter Macros (Reference: RM)======
#define RCC_CR_HSION          (1 &lt;&lt; 8)   // High-Speed Internal enable
#define RCC_CR_HSIRDY         (1 &lt;&lt; 10)  // HSI16 stability ready flag
#define RCC_AHB2ENR_GPIOBEN   (1 &lt;&lt; 1)   // GPIOB clock gating enable bit
#define RCC_APB1ENR1_TIM2EN   (1 &lt;&lt; 0)   // TIM2 clock gating enable bit

#define SW_HSI16              1          // HSI16 system source clock token
#define HPRE_DIV1             0          // No AHB prescaler division configuration

// Standardized GPIO Abstractions
#define GPIO_LOW              0
#define GPIO_HIGH             1

#define GPIO_INPUT            0
#define GPIO_OUTPUT           1
#define GPIO_ALT              2
#define GPIO_ANALOG           3

#define TIM_CR1_CEN           (1 &lt;&lt; 0)   // Counter Enable Bit
#define TIM_DIER_UIE          (1 &lt;&lt; 0)   // Update Interrupt Enable Bit
#define TIM_SR_UIF            (1 &lt;&lt; 0)   // Update Interrupt Status Flag
#define TIM_EGR_UG            (1 &lt;&lt; 0)   // Update Generation Latch Trigger

#define SYSTICK_ENABLE        (1 &lt;&lt; 0)   // Enable core counter ticking module
#define SYSTICK_TICKINT       (1 &lt;&lt; 1)   // Trigger core exception vector on rollover
#define SYSTICK_CLKSRC        (1 &lt;&lt; 2)   // Select internal processor core clock as source
#define NVIC_TIM2_IRQ_POS     28           // TIM2 Global Exception Vector position

// Target Frequency Baseline constant for internal math calculations
#define SYSTEM_CLOCK_FREQ     16000000

// ============================================================================
// Function Prototypes
// ============================================================================
// --- Core RCC Speed Drivers ---
static inline void driverSystemClockInit16MHz(void) {
    RCC-&gt;CR |= RCC_CR_HSION;
    while (!(RCC-&gt;CR & RCC_CR_HSIRDY)); 

    uint32_t cfg_temp = RCC-&gt;CFGR;
    cfg_temp &= ~(0x3 &lt;&lt; 0);
    cfg_temp |= SW_HSI16;
    RCC-&gt;CFGR = cfg_temp;
    while (((RCC-&gt;CFGR &gt;&gt; 2) & 0x3) != SW_HSI16);

    uint32_t hpre_temp = RCC-&gt;CFGR;
    hpre_temp &= ~(0xF &lt;&lt; 4);
    hpre_temp |= (HPRE_DIV1 &lt;&lt; 4);
    RCC-&gt;CFGR = hpre_temp;
}

// --- General Purpose I/O Port B Drivers ---

// From GPIO.c tutorial code
static inline void pinMode(int pin, int function) {
    switch(function) {
        case GPIO_INPUT:
            GPIOB-&gt;MODER &= ~(0b11 &lt;&lt; (2 * pin));
            break;
        case GPIO_OUTPUT:
            GPIOB-&gt;MODER |= (0b1 &lt;&lt; (2 * pin));
            GPIOB-&gt;MODER &= ~(0b1 &lt;&lt; (2 * pin + 1));
            break;
        case GPIO_ALT:
            GPIOB-&gt;MODER &= ~(0b1 &lt;&lt; (2 * pin));
            GPIOB-&gt;MODER |= (0b1 &lt;&lt; (2 * pin + 1));
            break;
        case GPIO_ANALOG:
            GPIOB-&gt;MODER |= (0b11 &lt;&lt; (2 * pin));
            break;
    }
}

// From GPIO.c tutorial code
static inline void digitalWrite(int pin, int val) {
    if (val == GPIO_HIGH) {
        GPIOB-&gt;ODR |= (1 &lt;&lt; pin);
    } else {
        GPIOB-&gt;ODR &= ~(1 &lt;&lt; pin);
    }
}

// From GPIO.c tutorial code
static inline void togglePin(int pin) {
    GPIOB-&gt;ODR ^= (1 &lt;&lt; pin);
}

// From GPIO.c tutorial code
static inline int digitalRead(int pin) {
    return (int)((GPIOB-&gt;IDR &gt;&gt; pin) & 1);
}

// --- Generic Time and Interrupt Peripherals Configurations ---
static inline void driverSysTickInit(void) {
    SysTick_Core-&gt;CTRL = 0;                                       
    SysTick_Core-&gt;LOAD = (SYSTEM_CLOCK_FREQ / 1000) - 1;             
    SysTick_Core-&gt;VAL  = 0;                                       
    SysTick_Core-&gt;CTRL = (SYSTICK_CLKSRC | SYSTICK_TICKINT | SYSTICK_ENABLE); 
}

static inline void driverTimer2InterruptInit(uint16_t prescalerValue) {
    RCC-&gt;AHB2ENR |= RCC_AHB2ENR_GPIOBEN;  
    RCC-&gt;APB1ENR1 |= RCC_APB1ENR1_TIM2EN; 

    TIM2-&gt;PSC = prescalerValue;                                               
    TIM2-&gt;DIER |= TIM_DIER_UIE;                                   

    // Set enable state safely inside the indexed array layout matrix
    NVIC_Core-&gt;ISER[NVIC_TIM2_IRQ_POS &gt;&gt; 5] |= (1 &lt;&lt; (NVIC_TIM2_IRQ_POS & 0x1F));
}

#endif

Hardware
The list of components used included:

1x E155 kit materials
1x Dual Seven-Segment Common-Anode Display (or 2x Single)
2x 2N3906 PNP transistors
4x 2N3904 NPN tansistors
1x 4x4 Matrix Keypad
2x 4-position DIP switch blocks (one on the E155 Development Board, other on the breadboard)
6x 1 kOhms resistors (transistors’ base current limiters, see “Calculations” section)
7x 220 ohms resistors (display cathodes’ current limiters, see “Calculations” section)
4x 330 ohms resistors (standard value for on-board LEDs’ current limiters in response to keypresses)
Use internal pullups for keypad columns

Resources used for hardware connections included:

E155 Development Board
2N3906 PNP Transistor Datasheet
2N3904 NPN Transistor Datasheet
MAN6400 Series Seven Segment Displays Datasheet OR HDSP Common Anode Seven-Segment Display Datasheet
HX-543 4x4 Matrix Membrane Keypad Datasheet

Due to the limited quantity of available FPGA pins that aren’t already used, the same pins were used for the keypad columns kp_col[3:0] and external breadboard DIP switch ext_in[3:0] because they are both 4-bit digital inputs. When testing the matrix keypad function, the external breadboard DIP switch must be completely turned off before pressing keys and observing the corresponding on-board LED behavior. When testing the seven-segment display multiplexer, flip the external breadboard switch as necessary for certain hexadecimal digits.


Verilog
Lab 2 modules included “counter_logic” and “seven_segment_decoder” from Lab 1. New modules included “keypad_scanner” and “lab2_tn” as the top-level module to tackle the challenge of creating a multiplexed seven-segment display and a 4x4 matrix keypad scanner with LED indicators.


Reveal System Verilog Code: counter_logic Module

/*-----------------------------------------------------------------------------
* Name:         Tiffany Nguyen
* Email:        tiffnguyen@g.hmc.edu
* Date:         September 12, 2026
*
* Purpose: A parameterized synchronous counter module used to track clock cycles up to a
* specified maximum value and toggle a signal at a desired frequency. Implemented in a single
* always_ff block with synchronous reset and enable controls to meet style specifications.
*---------------------------------------------------------------------------*/
`timescale 1 ns/1 ps
module counter_logic #(
   parameter int WIDTH     = 26,
   parameter int MAX_COUNT = 47999999
)(
   input  logic                    clk,     // Clock input
   input  logic                    reset_b, // Synchronous active-high reset
   input  logic                    enable,  // Active-high clock enable
   output logic [WIDTH-1:0]        count,   // Current count value output
   output logic                    out_clk  // Divided toggle output clock
);

   logic [WIDTH-1:0] count_reg = '0;
   logic state_reg = 1'b0;

   always_ff @(posedge clk) begin
       if (reset_b) begin
           count_reg &lt;= '0;
           state_reg &lt;= 1'b0;
       end else if (enable) begin
           if (count_reg &gt;= MAX_COUNT) begin
               count_reg &lt;= '0;
               state_reg &lt;= ~state_reg;
           end else begin
               count_reg &lt;= count_reg + 1'b1;
           end
       end
   end

   assign count   = count_reg;
   assign out_clk = state_reg;

endmodule



Reveal System Verilog Code: seven_segment_decoder Module

/*-----------------------------------------------------------------------------
* Name:         Tiffany Nguyen
* Email:        tiffnguyen@g.hmc.edu
* Date:         September 4, 2026
*
 * Purpose: This module uses a combinational logic block to decode the 4-bit binary input 
 * s[3:0] into hex digits (0 to F). A common-anode 7-segment display is used, so segments are 
 * active-low (driving 0 turns the segment ON, 1 turns it OFF). Formatted with explicit case 
 * handling to eliminate latch inference.
 * 
 * Let: seg[6:0] = {G, F, E, D, C, B, A} 
 * Logic behavior: 0 = ON, 1 = OFF 
*---------------------------------------------------------------------------*/
`timescale 1 ns/1 ps
module seven_segment_decoder (
   input  logic [3:0] binary_input,  // 4-bit input from DIP switches  / 4-bit hexadecimal input value
   output logic  [6:0] seg_output  // Recall how letting seg[0] = A and seg[6] = G, so let [6:G, 5:F, 4:E, 3:D, 2:C, 1:B, 0:A]
);

   always_comb begin
       case (binary_input)
           // Common-Anode: 0 = Segment ON, 1 = Segment OFF
           // Bits: [6:0] seg -&gt; G F E D C B A based on on letting seg[6] be G and seg[0] be A in Fig. 1 of E155 Lab 1 instructions
           4'h0: seg_output = 7'b1000000; // ‘0’
           4'h1: seg_output = 7'b1111001; // ‘ 1’
           4'h2: seg_output = 7'b0100100; // ‘2’
           4'h3: seg_output = 7'b0110000; // ‘3’
           4'h4: seg_output = 7'b0011001; // ‘4’
           4'h5: seg_output = 7'b0010010; // ‘5’
           4'h6: seg_output = 7'b0000010; // ‘6’, Unique from b
           4'h7: seg_output = 7'b1111000; // ‘7’
           4'h8: seg_output = 7'b0000000; // ‘8’, Unique from b (All segments ON)
           4'h9: seg_output = 7'b0010000; // ‘9’
           4'hA: seg_output = 7'b0001000; // ‘A’
           4'hb: seg_output = 7'b0000011; // Unique lowercase 'b' (to avoid looking like ‘6’ or ‘8’)
           4'hC: seg_output = 7'b1000110; // ‘C’
           4'hd: seg_output = 7'b0100001; // Unique lowercase ‘d’
           4'hE: seg_output = 7'b0000110; // ‘E’
           4'hF: seg_output = 7'b0001110; // ‘F’
           default: seg_output = 7'b1111111; // All segments OFF
       endcase
   end

endmodule



Reveal System Verilog Code: keypad_scanner Module

/*-----------------------------------------------------------------------------
* Name:         Tiffany Nguyen
* Email:        tiffnguyen@g.hmc.edu
* Date:         September 12, 2026
*
 * Purpose:  This module acts as a non-canonical state machine to rotate between outputting  
 * 1000, 0100, 0010, and 0001 at a toggle rate of 2 Hz by using a counter and some output 
 * logic. A matrix keypad is also used, where outputs are the rows and inputs are the columns of  
 * the keypad. 
 * Includes: Only includes instances of a counter_logic module and combinational assign 
 * statements that convert from the counter output to output values. It is also resettable and 
 * enable-able.  
*---------------------------------------------------------------------------*/
`timescale 1 ns/1 ps
module keypad_scanner #(
   parameter int SCAN_MAX_COUNT = 47999999
)(
   input  logic       clk_48mhz, // 48 MHz main internal clock
   input  logic       reset,     // Active-high reset
   input  logic       enable,    // Active-high enable
   output logic [3:0] row_out    // 4 active-high scanner row outputs
);

   logic [25:0] scan_count;
   int step_width;

   // Calculate quadrant boundaries dynamically based on parameter
   assign step_width = (SCAN_MAX_COUNT + 1) / 4;

   // Parameterized instance of the core Lab 1 counter module
   counter_logic #(
       .WIDTH(26),
       .MAX_COUNT(SCAN_MAX_COUNT)
   ) internal_scan_counter (
       .clk(clk_48mhz),
       .reset_b(reset),
       .enable(enable),
       .count(scan_count),
       .out_clk()
   );

   // Pure combinational mapping to prevent latches or sequential elements
   assign row_out = (scan_count &lt; step_width)         ? 4'b1000 :
                    (scan_count &lt; (step_width * 2))   ? 4'b0100 :
                    (scan_count &lt; (step_width * 3))   ? 4'b0010 : 4'b0001;

endmodule



